import java.util.*;

class Solution {
  public int[] leftmostBuildingQueries(int[] heights, int[][] queries) {
    int size = 1;
    while (size < heights.length) size <<= 1;
    int[] tree = new int[size << 1];
    Arrays.fill(tree, Integer.MIN_VALUE);
    for (int i = 0; i < heights.length; i++) tree[size + i] = heights[i];
    for (int i = size - 1; i > 0; i--) tree[i] = Math.max(tree[i << 1], tree[i << 1 | 1]);
    int[] answer = new int[queries.length];
    for (int q = 0; q < queries.length; q++) {
      int a = queries[q][0], b = queries[q][1];
      if (a > b) {
        int t = a;
        a = b;
        b = t;
      }
      if (a == b || heights[a] < heights[b]) answer[q] = b;
      else answer[q] = firstGreater(tree, size, b + 1, heights[a]);
    }
    return answer;
  }

  private int firstGreater(int[] tree, int size, int from, int value) {
    return firstGreater(tree, 1, 0, size - 1, from, value);
  }

  private int firstGreater(int[] tree, int node, int left, int right, int from, int value) {
    if (right < from || tree[node] <= value) return -1;
    if (left == right) return left;
    int mid = (left + right) >>> 1;
    int result = firstGreater(tree, node << 1, left, mid, from, value);
    return result != -1 ? result : firstGreater(tree, node << 1 | 1, mid + 1, right, from, value);
  }
}
